import { dayAr, formatAr, percentAr, postsAr, commentsAr, pagesAr } from "./text";
import { regionNameAr } from "../regionNames";
import type { ReportModel, ReportPayload } from "./aggregate";

/**
 * The analytical conclusions and the honest limits of the methodology PDF. EVERY sentence is a template filled with numbers computed from the delivered data
 * (`buildReportModel`): nothing is written by hand and nothing is generated by a model. A sentence that interprets (a guess about what a number means) is labelled
 * «اجتهاد» and appears only when a stated numeric condition holds; otherwise there is no interpretation at all.
 */
export const GUESS_LABEL_AR = "اجتهاد";

const quote = (name: string): string => `«${name}»`;
const days = (n: number): string => (n === 1 ? "يوم واحد" : n === 2 ? "يومان" : `${formatAr(n)} ${n <= 10 ? "أيام" : "يومًا"}`);

const periodDays = (from: string, to: string): number => Math.floor((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000) + 1;

export function conclusionsAr(payload: ReportPayload, model: ReportModel): string[] {
  const out: string[] = [];
  const total = model.kpis.posts;
  if (total === 0) return ["لا توجد منشورات مسلَّمة، فلا تُستخلص أرقام تحليلية."];
  const byPosts = model.axes[0];
  out.push(`تصدّر محور ${quote(byPosts.nameAr)} المنشورات بعدد ${postsAr(byPosts.posts)} (${percentAr(byPosts.share)} من ${postsAr(total)}).`);
  const byComments = [...model.axes].sort((a, b) => b.comments - a.comments || a.rank - b.rank)[0];
  if (model.kpis.comments > 0) {
    out.push(byComments.axisId === byPosts.axisId
      ? `وهو نفسه أعلى المحاور تعليقًا بعدد ${commentsAr(byComments.comments)} (${percentAr(byComments.comments / model.kpis.comments)} من التعليقات المسلَّمة).`
      : `وكان أعلى المحاور تعليقًا محور ${quote(byComments.nameAr)} بعدد ${commentsAr(byComments.comments)} (${percentAr(byComments.comments / model.kpis.comments)} من التعليقات المسلَّمة).`);
  }
  const byReactions = [...model.axes].sort((a, b) => b.reactions - a.reactions || a.rank - b.rank)[0];
  if (model.kpis.reactions > 0) out.push(`وجاء محور ${quote(byReactions.nameAr)} في المرتبة الأولى بالتفاعلات بمجموع ${formatAr(byReactions.reactions)} تفاعلًا (${percentAr(byReactions.reactions / model.kpis.reactions)} من إجمالي ${formatAr(model.kpis.reactions)}).`);
  const byShares = [...model.axes].sort((a, b) => b.shares - a.shares || a.rank - b.rank)[0];
  if (model.kpis.shares > 0) out.push(`وجاء محور ${quote(byShares.nameAr)} في المرتبة الأولى بالمشاركات بمجموع ${formatAr(byShares.shares)} مشاركة (${percentAr(byShares.shares / model.kpis.shares)} من إجمالي ${formatAr(model.kpis.shares)}).`);
  const top = model.top[0];
  if (top) out.push(`أكثر المنشورات تفاعلًا نشره ${quote(top.post.publisher)}${top.post.publishedAtMs ? ` بتاريخ ${dayAr(new Date(top.post.publishedAtMs).toISOString().slice(0, 10))}` : ""}، وبلغ مجموع تفاعله ومشاركاته وتعليقاته ${formatAr(top.interactions)}.`);
  const lead = model.concentration[0];
  out.push(`أكبر الناشرين حصة هو ${quote(lead.name)} بنسبة ${percentAr(lead.share)} من المنشورات المسلَّمة (${postsAr(lead.posts)})، من أصل ${formatAr(model.concentration.length)} ${model.concentration.length <= 10 ? "ناشرين" : "ناشرًا"}.`);
  out.push(`متوسط التعليقات المسلَّمة لكل منشور ${formatAr(Math.round((model.kpis.comments / total) * 10) / 10, 1)}، ومتوسط التفاعلات لكل منشور ${formatAr(Math.round(model.kpis.reactions / total))}.`);
  const videos = model.posts.filter((post) => post.contentType === "video").length;
  out.push(`بلغت نسبة الفيديوهات والريلز ${percentAr(videos / total)} من المنشورات (${postsAr(videos)}).`);
  const general = model.axes.find((axis) => axis.axisId === "general");
  if (general) out.push(`ولم تُنسب ${postsAr(general.posts)} (${percentAr(general.share)}) إلى محور محدد فصُنّفت ضمن «موضوعات صحية عامة».`);
  // a guess, only when a stated condition holds: an axis whose comments per post are at least twice the overall average (with at least 3 posts)
  const overall = model.kpis.comments / total;
  const heated = model.axes.filter((axis) => axis.posts >= 3 && overall > 0 && axis.comments / axis.posts >= 2 * overall).sort((a, b) => b.comments / b.posts - a.comments / a.posts)[0];
  if (heated) out.push(`${GUESS_LABEL_AR} (غير مقاس): بلغ متوسط التعليقات لكل منشور في محور ${quote(heated.nameAr)} ${formatAr(Math.round((heated.comments / heated.posts) * 10) / 10, 1)} مقابل ${formatAr(Math.round(overall * 10) / 10, 1)} لمجموع المنشورات، وقد يدل ذلك على نقاش أكبر حول هذا المحور؛ هذا تفسير محتمل لا تثبته الأرقام وحدها.`);
  return out;
}

/** The honest limits, with the real counts of this job. */
export function limitsAr(payload: ReportPayload, model: ReportModel): string[] {
  const c = payload.collection;
  const lines: string[] = [];
  lines.push("يقرأ المصدر أحدث منشورات كل صفحة أولًا ثم الأقدم، فلا تمثّل العينة كل ما نُشر في الفترة ولا تُعدّ عينة إحصائية ممثِّلة للمجتمع.");
  lines.push(`قد يهيمن ناشر واحد على النتائج؛ لذلك حُدّد لكل ناشر حدّ أقصى ${percentAr(c.shareConfigured)} من المنشورات المسلَّمة${c.shareEffective > c.shareConfigured + 1e-9 ? `، وطُبّق ${percentAr(c.shareEffective)} لأن عدد الصفحات المتاحة (${formatAr(c.pagesBrowsed)}) لا يسمح بالحد الأدنى`  : ""}${c.selectionDropped > 0 ? `، واستُبعد ${postsAr(c.selectionDropped)} فائضة عن هذا الحد أو عن العدد المطلوب` : ""}.`);
  lines.push(`طُبّقت الفترة المطلوبة على تاريخ كل منشور بالأيام الكاملة (بتوقيت التوقيت العالمي)؛ استُبعد ${postsAr(c.postsOutsideWindow)} خارج الفترة و${postsAr(c.postsUndated)} بلا تاريخ يمكن التحقق منه، ومن أصل ${postsAr(c.postsFound)} وُجدت.`);
  lines.push(`صُنّف كل منشور بقواعد نصية ثابتة على نصه؛ والمنشورات التي لم تحسمها القواعد عُرضت على نموذج ذكاء اصطناعي في دفعات (${formatAr(c.modelCalls)} استدعاء) ضمن حد تكلفة محدد، وما تجاوز الحد (${postsAr(c.modelBudgetStopped)}) أو تعذّر تصنيفه (${postsAr(c.modelFailed)}) وُضع في «موضوعات صحية عامة» وهو مُعلَّم في بيانات الطلب.`);
  lines.push(`لم تُقيَّم التعليقات ولم تُنتقَ؛ أُخذت كما أعادها المصدر مع حذف الفارغ منها (${formatAr(c.commentsEmpty)}) والمكرر (${formatAr(c.commentsDuplicates)}) وما كان رابطًا فقط (${formatAr(c.commentsLinkOnly)}).`);
  if (c.commentsNotReturned > 0) lines.push(`لم يُعد المصدر ${commentsAr(c.commentsNotReturned)} من منشورات تحمل تعليقات، ولم يُحتسب عليك شيء مقابلها.`);
  if (c.searchPosts > 0 || c.searchCalls > 0) lines.push(`استُكملت العينة بمنشورات من بحث بالكلمات المفتاحية بعدد ${postsAr(c.searchPosts)} (حدّها الأقصى ${percentAr(0.15)} من المنشورات)؛ واستُبعد ${postsAr(c.searchRejectedCountry)} منها لأنها لم تُثبت انتماءها إلى ${regionNameAr(payload.request.region) ?? "الدولة المطلوبة"}.`);
  lines.push("أرقام التفاعلات والمشاركات والتعليقات هي ما أظهرته المنصة لحظة الجمع، وقد تتغير بعد ذلك.");
  return lines;
}

/** The scope lines at the top of the PDF: what was asked, what was covered, and how many Pages were used (never a provider name). */
export function scopeLinesAr(payload: ReportPayload, model: ReportModel): string[] {
  const c = payload.collection;
  const country = regionNameAr(payload.request.region);
  const requestedDays = periodDays(payload.request.from, payload.request.to);
  const lines = [
    `الموضوع: ${payload.request.topic}${country ? ` — ${country}` : ""}`,
    `الفترة المطلوبة: من ${dayAr(payload.request.from)} إلى ${dayAr(payload.request.to)} (${days(requestedDays)})`,
    model.covered.from
      ? `الفترة التي غطّتها المنشورات فعلًا: من ${dayAr(model.covered.from)} إلى ${dayAr(model.covered.to)} (${days(model.covered.days)})`
      : "الفترة التي غطّتها المنشورات فعلًا: غير متاحة",
    `الصفحات: استُخدمت ${pagesAr(c.pagesBrowsed)} من ${pagesAr(c.pagesMatching)} مطابقة للدولة والموضوع، وتُخطّيت ${pagesAr(c.pagesSkipped)}`,
    `المنشورات المسلَّمة: ${postsAr(model.kpis.posts)} من ${postsAr(payload.request.postsTarget)} مطلوبًا؛ والتعليقات المسلَّمة: ${commentsAr(model.kpis.comments)} من ${commentsAr(payload.request.commentsTarget)} مطلوبًا`,
  ];
  return lines;
}
